const $=s=>document.querySelector(s);
const paths={home:'M3 10 12 3l9 7v10H15v-7H9v7H3Z',explore:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM16 8l-3 5-5 3 3-5Z',simulate:'M6 6v6l6 6 6-6V6M9 4a3 3 0 1 1-6 0 3 3 0 0 1 6 0ZM21 4a3 3 0 1 1-6 0 3 3 0 0 1 6 0ZM15 20a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',account:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM4 21v-3a8 8 0 0 1 16 0v3Z',arrow:'M5 12h14m-6-6 6 6-6 6',back:'m15 5-7 7 7 7',up:'m6 15 6-6 6 6',down:'m6 9 6 6 6-6',check:'m5 12 4 4L19 6',pin:'M19 9c0 5-7 12-7 12S5 14 5 9a7 7 0 0 1 14 0ZM14 9a2 2 0 1 1-4 0 2 2 0 0 1 4 0Z',save:'M6 3h12v18l-6-4-6 4Z',lens:'M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',ask:'M4 4h16v13H9l-5 4ZM8 9h8m-8 4h5',translate:'M3 5h12M9 2v3m-4 0c1 5 4 8 8 10m0-10C12 9 8 13 3 15m10 6 5-12 5 12m-8-4h6',close:'m6 6 12 12M6 18 18 6',time:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM12 7v5l3 2',map:'m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2ZM9 3v16m6-14v16'};
paths.undo='M3 10h6M3 10V4m0 6a9 9 0 1 1 1 8';
paths.flag='M5 21V3m0 1c5-4 9 4 14 0v10c-5 4-9-4-14 0';
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.pin}"/></svg>`;

const state={tab:'home',screen:'home',plan:{start:'market',end:'baillieu',mode:'destination',travel:'Walk',time:60,interests:['Coffee','Culture']},route:null,draft:null,selected:null,role:'end',candidate:null,pickerFrom:'plan',query:'',step:0,undo:null,discoveryFilter:'All',spotId:null,spotFrom:'preview'};
const clone=x=>JSON.parse(JSON.stringify(x));
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),2200)}
function btn(text,action,cls='primary',extra=''){return `<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`}
function head(title,back='back',right=''){return `<header class="topbar">${btn(icon('back'),back,'iconbtn','aria-label="Back"')}<strong role="heading" aria-level="1" tabindex="-1">${title}</strong>${right||'<span style="width:48px"></span>'}</header>`}
function brand(label){return `<div class="brand"><div class="logo" role="img" aria-label="Day One"></div><span class="meta">${label}</span></div>`}
function end(){return state.plan.mode==='return'?state.plan.start:state.plan.end}
function total(r){return r?routeMetrics(r).total:0}
function budget(r){let diff=state.plan.time-total(r);return `<div class="notice ${diff<0?'warning':''}">${diff<0?`${-diff} min over your ${state.plan.time}-min budget. Remove a stop or change your time.`:`${diff} min to spare within your ${state.plan.time}-min break.`}</div>`}
function home(){return `<header class="brand home-header"><div class="logo" role="img" aria-label="Day One"></div><div class="home-location"><span class="meta">Melbourne · Carlton</span>${askLanguageButton()}</div></header><h1 class="home-title">Make today local.</h1><section class="section home-tools"><div class="row"><h2>Tools</h2></div><div class="tools">${[['lens','AR Lens'],['ask','Ask This Place'],['simulate','Simulate Scenario'],['translate','Translate Sign']].map(([i,t])=>`<${i==='lens'||i==='ask'||i==='simulate'?'button':'div'} class="tool" ${i==='lens'?'data-action="ar-open"':i==='ask'?'data-action="ask-place"':i==='simulate'?'data-action="scenario-select"':''}>${icon(i)}<span>${t}</span></${i==='lens'||i==='ask'||i==='simulate'?'button':'div'}>`).join('')}</div></section><section class="section card hero home-trip"><img class="photo" src="assets/city.jpg" alt="A tram on a leafy Melbourne street"><div class="pad"><div class="home-trip-copy"><h2>Your next Short Trip</h2><p>Coffee, culture & a little discovery.</p></div>${btn('Plan a trip','plan')}</div></section><section class="section home-discoveries"><div class="row"><h2>Your little discoveries</h2>${btn('See all '+icon('arrow'),'explore','link')}</div><div class="cards"><div class="card"><img class="photo" src="assets/coffee.jpg" alt="Coffee beside a window"><div class="pad"><h3>A coffee pause</h3></div></div><div class="card"><img class="photo" src="assets/place-quad.jpg" alt="Historic arches at the Old Quad"><div class="pad"><h3>A new city corner</h3></div></div><div class="card"><img class="photo" src="assets/place-system.jpg" alt="A leafy corner of System Garden"><div class="pad"><h3>A little guidance. A little discovery.</h3></div></div></div></section>`}
function explore(){return `${brand('Short Trip')}<h1>Where to today?</h1><p>Discover local places at your own pace.</p>${map()}<div class="card section"><div class="field">${icon('pin')}<div><small>From · sample trip</small><strong>${places[state.plan.start].name}</strong></div>${btn('Change','place','link','data-role="start"')}</div></div><div class="section">${btn('Plan your short trip '+icon('arrow'),'plan')}</div><section class="section"><div class="row"><h2>Routes to try</h2><span class="tag">Local picks</span></div><div class="cards">${templates.slice(0,2).map((r,i)=>`<button class="card" data-action="quick" data-id="${r.id}"><img class="photo" src="assets/${routePhotos[r.id].explore}" alt="${routePhotos[r.id].alt}"><div class="pad"><h3>${r.name}</h3><p>${r.stops.length} ${r.stops.length===1?'stop':'stops'} · Customisable</p><span class="link">Preview route →</span></div></button>`).join('')}</div></section>`}
function plan(){return `${head('Plan your short trip','root')}${map()}<div class="segment" aria-label="Trip type">${['destination','return'].map(m=>btn(m==='return'?'Return to start':'Go somewhere','mode',state.plan.mode===m?'active':'',`data-id="${m}" aria-pressed="${state.plan.mode===m}"`)).join('')}</div><div class="card">${[['start','From'],...(state.plan.mode==='destination'?[['end','To']]:[])].map(([id,l])=>`<div class="field">${icon('pin')}<div><small>${l}</small><strong>${places[state.plan[id]].name}</strong></div>${btn('Change','place','link',`data-role="${id}"`)}</div>`).join('')}</div><section class="section"><h3>Travel by</h3><div class="segment">${['Walk','Bike','Transit'].map(t=>btn(t==='Transit'?'Transport':t,'travel',t===state.plan.travel?'active':'',`data-id="${t}" aria-pressed="${t===state.plan.travel}"`)).join('')}</div></section><section class="section"><div class="row"><label for="time"><strong>Time available</strong></label><strong id="time-value" style="color:var(--blue)">${state.plan.time} min</strong></div><input id="time" type="range" min="15" max="120" step="5" value="${state.plan.time}"><div class="row meta"><span>15 min</span><span>Includes travel & stops</span><span>120 min</span></div></section><section class="section planner-scene"><h3>Your day</h3><div class="chips">${planningScenes.map(([id,en,zh])=>btn(storyText(en,zh),'plan-scene',`chip ${(state.plan.scene||'first-week')===id?'active':''}`,`data-id="${id}" aria-pressed="${(state.plan.scene||'first-week')===id}"`)).join('')}</div></section><section class="section"><h3>What would you like to discover?</h3><div class="chips">${planningThemes.map(t=>btn(t,'interest',`chip ${state.plan.interests.includes(t)?'active':''}`,`data-id="${t}" aria-pressed="${state.plan.interests.includes(t)}"`)).join('')}</div></section><p class="meta section">${state.plan.travel==='Walk'?'Walkable detours, with pauses included.':state.plan.travel==='Bike'?'Ride between places; unlock and parking time included.':'Walk + tram corridor; sample waiting time included.'}</p><div class="bottom-action">${btn('Find routes '+icon('arrow'),'find')}</div>`}
function picker(isMap=false){return `${head(isMap?'Choose on map':`Change ${state.role==='start'?'starting point':'destination'}`,isMap?'picker':'picker-cancel',btn('Cancel','picker-cancel','link'))}${isMap?`<p>Tap a marked place to choose it.</p>${map([],true,true)}`:`<label for="search" class="meta">Search places on this walk</label><input type="search" id="search" placeholder="Search a place" value="${state.query.replaceAll('&','&amp;').replaceAll('"','&quot;').replaceAll('<','&lt;')}"><div class="section">${btn(icon('map')+' Choose on map','picker-map','secondary')}</div><h3 class="section">Places</h3><div class="card section" id="place-results">${placeResults()}</div>`}<div class="section card pad"><small>${state.role==='start'?'Start here':'Your route ends here'}</small><h3 id="candidate-name">${places[state.candidate].name}</h3></div><div class="bottom-action">${btn(`Use this ${state.role==='start'?'starting point':'destination'}`,'place-confirm')}</div>`}
function placeResults(){let entries=Object.entries(places).filter(([id,p])=>p.name.toLowerCase().includes(state.query.toLowerCase()));return entries.length?entries.map(([id,p])=>`<button class="choice ${state.candidate===id?'selected':''}" data-action="choose-place" data-id="${id}"><span><strong>${p.name}</strong><small>${p.area}</small></span>${state.candidate===id?icon('check'):icon('pin')}</button>`).join(''):'<p class="pad">No places match this collection. Try “library” or choose on the map.</p>'}
function routeKey(){return JSON.stringify([state.plan.start,end(),state.plan.travel,state.route.stops])}
function isSaved(){return saved.some(s=>s.key===routeKey())}
function placeImage(id){const p=places[id];if(p.imagePath)return p.imagePath;return `assets/place-${id}.${p.photo?'jpg':'svg'}`}
function timeline(r,edit=false){return `<div class="card timeline ${edit?'editable-timeline':''}" ${edit?'id="route-dropzone" aria-label="Your route. Drop discovery cards between stops."':''}><div class="endline endpoint"><span class="endpoint-dot">S</span><div><small>Start</small><strong>${places[state.plan.start].name}</strong></div></div>${r.stops.map((id,i)=>`<div class="stop" data-stop-index="${i}" data-stop-id="${id}"><span class="stop-visual"><img src="${placeImage(id)}" alt="" draggable="false"><span class="number">${i+1}</span></span><div class="info">${btn(`<strong>${places[id].short}</strong><small>${places[id].stay} min · ${places[id].category}</small><span class="stop-reason">${stopReasons[id]}</span>`,'spot','stop-name',`data-id="${id}" aria-label="${places[id].name}. ${stopReasons[id]}"`)}</div>${edit?`${btn('•••','reveal-delete','inline-stop-action',`data-index="${i}" data-name="${places[id].name}" aria-label="Show delete button for ${places[id].name}"`)}<button class="drag-handle iconbtn" data-drag-id="${id}" data-drag-from="route" aria-label="Reorder ${places[id].name}. Press space, use arrow keys, then Enter.">⠿</button>`:''}</div>`).join('')}<div class="endline endpoint finish-point"><span class="endpoint-dot">E</span><div><small>${state.plan.mode==='return'?'Return':'Finish'}</small><strong>${places[end()].name}</strong></div></div></div>`}
function previewTimeline(r,editing=false){return `<div class="preview-timeline ${editing?'inline-timeline':''}" ${editing?'id="route-dropzone" aria-label="Your route. Drop discoveries between stops."':''}><div class="preview-node endpoint-node"><span class="node-marker">${icon('pin')}</span><div class="node-copy"><div class="row"><strong>${places[state.plan.start].name}</strong><small>Start</small></div><p>${state.plan.start==='market'?'Queen Street meeting point':places[state.plan.start].area}</p></div></div>${r.stops.map((id,i)=>`<div class="preview-node ${editing?'stop':''}" data-stop-index="${i}" data-stop-id="${id}"><span class="node-marker numbered">${i+1}</span><div class="stop-surface"><img class="node-photo" src="${placeImage(id)}" alt="" draggable="false"><button class="node-copy node-detail" data-action="spot" data-id="${id}" aria-label="${places[id].name}. ${stopReasons[id]}"><strong>${places[id].short}</strong><small>${places[id].stay} min</small><p>${stopReasons[id]}</p></button>${editing?`${btn('•••','reveal-delete','inline-stop-action',`data-index="${i}" data-name="${places[id].name}" aria-label="Show delete button for ${places[id].name}"`)}<button class="drag-handle iconbtn" data-drag-id="${id}" data-drag-from="route" aria-label="Reorder ${places[id].name}. Press space, arrow keys, then Enter.">⠿</button>`:''}</div></div>`).join('')}<div class="preview-node endpoint-node finish-node finish-point"><span class="node-marker">${icon('flag')}</span><div class="node-copy"><div class="row"><strong>${places[end()].name}</strong><small>${state.plan.mode==='return'?'Return':'Finish'}</small></div><p>Finish outside ${places[end()].short}.</p>${editing?'':`<a href="${places[end()].source}" target="_blank" rel="noopener">Check current access ↗</a>`}</div></div></div>`}
function preview(){if(state.inlineEditing)return routeBuilder();let editing=!!state.inlineEditing,r=editing?state.draft:state.route,m=routeMetrics(r),spare=state.plan.time-total(r);return `${head('Your short trip',r.fromChat?'ask-place':'compare',btn(icon('save'),'save','iconbtn',`aria-label="${isSaved()?'Unsave':'Save'} route" aria-pressed="${isSaved()}"`))}<div class="preview-map">${map(r.stops,true)}</div><div class="preview-body"><span class="tag">${r.fromChat?'From your conversation':r.id==='custom'?'Your own route':'Curated route'}</span><h1 class="backtitle">${r.name}</h1><div class="preview-metrics"><div>${icon('time')}<span><strong>${total(r)} min</strong><small>total</small></span></div><div>${icon('pin')}<span><strong>${r.stops.length}</strong><small>${r.stops.length===1?'stop':'stops'}</small></span></div><div>${icon('map')}<span><strong>${(m.metres/1000).toFixed(1)} km</strong><small>${state.plan.travel==='Walk'?'walk':state.plan.travel==='Bike'?'ride':'travel'}</small></span></div></div><p class="preview-spare ${spare<0?'over-budget':''}">${spare<0?`${-spare} min over budget`:`${spare} min to spare`}</p><section class="preview-stops"><div class="row"><h2>${editing?'Customize your stops':'Your stops'}</h2>${editing?`${state.undo?btn('Undo','undo','link'):''}${btn('Cancel','edit-cancel','link')}`:btn('Edit stops','edit','link')}</div>${editing?discoveryPanel():''}${editing?`<p class="drag-hint" id="drag-hint">Drag a discovery into your route. Drag ⠿ to reorder.</p>${previewTimeline(r,true)}`:previewTimeline(r)}${!editing&&r.id==='custom'&&!r.stops.length?`<div class="notice"><p>No stops added yet.</p>${btn('Add your first stop','edit','secondary')}</div>`:''}</section>${editing?'':`<p class="preview-demo">${r.fromChat?'Illustrative market route · Follow on-site signs':planningModeNote(r)}</p>`}</div><div class="bottom-action">${editing?btn('Use this route','edit-confirm','primary',spare<0?'disabled':''):btn('Start trip '+icon('arrow'),'start','primary',spare<0?'disabled':'')}${spare<0?btn('Change time budget','plan','link'):''}</div>`}
function routeBuilder(){const r=state.draft,m=routeMetrics(r),over=m.total-state.plan.time,ratio=Math.min(1,m.total/state.plan.time);return `${head('Build your short trip','edit-cancel')}<div class="preview-map canvas-dropzone" id="route-dropzone" aria-label="Map canvas. Drag a place onto a route segment to insert it.">${map(r.stops,true)}</div><div class="preview-body canvas-ui"><section class="canvas-budget ${over>0?'is-over':''}" id="builder-budget"><div class="canvas-time"><span class="time-dial" style="--used:${ratio*100}%">${icon('time')}</span><div><strong>${m.total}<span> min</span></strong><small>of ${state.plan.time} min</small></div></div><div class="canvas-budget-right"><span id="builder-alert" role="status" aria-live="polite">${over>0?`${over} min over`:`${-over} min to play with`}</span><div class="canvas-budget-actions">${state.undo?btn(icon('undo'),'undo','iconbtn','aria-label="Undo last change"'):''}${btn(icon('time'),'builder-time','iconbtn','aria-label="Change time budget"')}</div></div><div class="canvas-time-track"><span style="width:${ratio*100}%"></span></div></section><div class="canvas-instruction" id="drag-hint" aria-live="polite">${icon('pin')}<span>Drag a place onto the blue route</span></div><section class="canvas-shelf" aria-label="Route and nearby places"><div class="route-rail" aria-label="Your route order"><span class="rail-end" title="${places[state.plan.start].name}">S</span>${r.stops.map((id,i)=>`<article class="rail-stop stop" data-stop-id="${id}" data-stop-index="${i}"><button class="rail-stop-drag" data-drag-id="${id}" data-drag-from="route" aria-label="Reorder ${places[id].name}. Press space, arrows, then Enter."><span>${i+1}</span><strong>${places[id].short}</strong></button>${btn(icon('close'),'remove','rail-remove',`data-index="${i}" aria-label="Remove ${places[id].name}"`)}</article>`).join('')||'<span class="rail-empty">Your first stop goes here</span>'}<span class="rail-end finish-point">E</span></div><div class="shelf-heading"><div><span class="eyebrow">A little off your path</span><h2>Worth a detour</h2></div><span>${discoveries().length} nearby</span></div><div class="discovery-deck">${discoveries().map(id=>`<article class="canvas-place"><button class="canvas-place-drag" data-drag-id="${id}" data-drag-from="discovery" data-action="spot" data-id="${id}" aria-label="Drag ${places[id].name} onto the map, or tap for details"><img src="${placeImage(id)}" alt="" draggable="false"><span><strong>${places[id].short}</strong><small>${places[id].category} <b>·</b> ${places[id].stay} min</small></span><span class="place-grip" aria-hidden="true">⠿</span></button>${btn('+','add','canvas-add',`data-id="${id}" aria-label="Add ${places[id].name}"`)}</article>`).join('')||'<div class="canvas-all-added">Every detour is on your route. Make it your own above.</div>'}</div></section></div><div class="bottom-action canvas-action"><div class="canvas-distance">${icon('map')}<span><strong>${(m.metres/1000).toFixed(1)} km</strong><small>${r.stops.length} ${r.stops.length===1?'stop':'stops'} · ${state.plan.travel.toLowerCase()}</small></span></div>${btn('This is my route '+icon('arrow'),'edit-confirm','primary')}</div>`}
function warnBuilderBudget(){if(!state.inlineEditing||!state.draft)return false;const over=total(state.draft)-state.plan.time;if(over<=0)return false;const el=$('#builder-budget');if(el&&!matchMedia('(prefers-reduced-motion: reduce)').matches)el.animate([{transform:'translateX(0)'},{transform:'translateX(-6px)'},{transform:'translateX(6px)'},{transform:'translateX(-4px)'},{transform:'translateX(4px)'},{transform:'translateX(0)'}],{duration:360,easing:'ease-out'});toast(`${over} min over your limit. Remove a stop or increase the time.`);return true}
function openBuilderTime(){const d=document.createElement('dialog');d.id='builder-time-dialog';d.innerHTML=`<form method="dialog"><h2>Time available</h2><p>Your route needs ${total(state.draft)} min.</p><label for="builder-time-range">Time budget <output id="builder-time-value">${state.plan.time} min</output></label><input id="builder-time-range" type="range" min="15" max="120" step="5" value="${state.plan.time}"><div class="row"><button class="secondary" value="cancel">Cancel</button>${btn('Apply','builder-time-apply','primary','type="button"')}</div></form>`;document.body.append(d);d.addEventListener('close',()=>{d.remove();$('#builder-budget button')?.focus({preventScroll:true})});d.showModal()}
function discoveries(){return Object.keys(places).filter(id=>!id.startsWith('ask-')&&places[id].stay&&!state.draft.stops.includes(id)&&id!==state.plan.start&&id!==end())}
function discoveryPanel(){return `<section class="discovery-section" aria-labelledby="nearby-heading"><div class="row"><h3 id="nearby-heading">Nearby discoveries</h3><div class="deck-controls">${btn('‹','deck-prev','iconbtn','aria-label="Previous discoveries"')}${btn('›','deck-next','iconbtn','aria-label="More discoveries"')}</div></div><div class="discovery-deck">${discoveries().map(id=>{let p=places[id];return `<article class="discovery-card"><button class="discovery-open" data-drag-id="${id}" data-drag-from="discovery" data-action="spot" data-id="${id}" aria-label="About ${p.name}"><img src="${placeImage(id)}" alt="${p.name}" draggable="false"><span class="discovery-copy"><strong>${p.name}</strong><small>${p.stay} min</small></span></button><div class="discovery-actions">${btn('+ Add','add','link',`data-id="${id}" aria-label="Add ${p.name} to end of route"`)}</div></article>`}).join('')||'<p class="meta">All nearby discoveries are in your route.</p>'}</div></section>`}
function edit(){return preview()}
let placeModalFocus=null;
function closePlaceModal(){const d=$('#place-dialog');if(!d)return;d.close();d.remove();placeModalFocus?.focus({preventScroll:true})}
function placeGuide(id){const p=places[id],g=placeGuides[id];if(!g)return `<p>${p.desc}</p>`;const source=g.source||p.source,reviews='https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(p.name+' '+p.area);return `<section class="guide-section guide-intro"><h3>New here? Start with this.</h3><p>${g.why}</p><div class="guide-pause">${icon('time')}<span>${p.stay?p.stay+' min':'A short'} suggested pause</span></div></section><section class="guide-section"><h3>${g.label}</h3><ul class="guide-picks">${g.picks.map(([name,copy])=>`<li><strong>${name}</strong><p>${copy}</p></li>`).join('')}</ul>${g.menu?`<a class="guide-source-link" href="${g.menu}" target="_blank" rel="noopener">View the café’s linked menu ↗</a>`:''}</section>${g.gifts?`<section class="guide-section"><h3>A little something to take home</h3><ul class="guide-picks">${g.gifts.map(([name,copy])=>`<li><strong>${name}</strong><p>${copy}</p></li>`).join('')}</ul></section>`:''}<section class="guide-section guide-practical"><h3>Before you go</h3><p>${g.tip}</p><a class="guide-source-link" href="${source}" target="_blank" rel="noopener">${g.sourceLabel||p.sourceName} ↗</a></section><section class="guide-section"><h3>Visitor reviews</h3><p>${g.reviewHint||'Check recent visitor comments and photos before deciding whether this stop suits you.'}</p><a class="secondary guide-reviews" href="${reviews}" target="_blank" rel="noopener">Read reviews on Google Maps ${icon('arrow')}</a></section><p class="guide-verification">Day One suggestions for new international students. Venue information checked 15 Oct 2026; menus, prices and access can change. Visitor ratings are viewed on Google Maps.</p>`}
function openPlaceModal(id){closePlaceModal();placeModalFocus=document.activeElement;const p=places[id],d=document.createElement('dialog');d.id='place-dialog';d.setAttribute('aria-labelledby','place-dialog-title');d.innerHTML=`<div class="place-dialog-topbar"><strong>Place guide</strong>${btn(icon('close'),'modal-close','iconbtn modal-close','aria-label="Close place details"')}</div><img class="place-dialog-photo" src="${placeImage(id)}" alt="${p.name}"><div class="place-dialog-copy"><span class="tag">${p.category}</span><h2 id="place-dialog-title">${p.name}</h2><p>${p.area}</p>${placeGuide(id)}${state.inlineEditing&&!state.draft.stops.includes(id)?btn('Add to my route','modal-add','primary',`data-id="${id}"`):''}</div>`;document.body.append(d);d.addEventListener('cancel',e=>{e.preventDefault();closePlaceModal()});d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closePlaceModal()}});d.showModal();d.querySelector('.modal-close').focus()}

function spot(){const id=state.spotId,p=places[id];return `${head('A little discovery','spot-back')}<img class="spot-photo card" src="${placeImage(id)}" alt="${p.name}"><span class="tag section">${p.category}</span><h1 class="backtitle">${p.name}</h1><p>${p.area}</p><div class="place-guide">${placeGuide(id)}</div>${state.spotFrom==='edit'&&!state.draft.stops.includes(id)?`<div class="bottom-action">${btn('Add to my route','add-from-spot')}</div>`:''}`}

const askTopics=[['explore','Where do I start?','First-time visit'],['food','Find food & stalls','Local picks & locations'],['ask','Shopping help','English & payments'],['pin','Find essentials','Toilets, hours & help']];
paths.food='M6 3v7m-3-7v4a3 3 0 0 0 6 0V3M6 10v11M18 3c-3 3-3 7 0 8h2V3h-2Zm2 8v10';
let askMessages=[],askScenario=null,askTurn=0,askDraft='',askPending=false,askTimer=null,askGeneration=0;
