function askDone(){return !!askScenario&&!askPending&&askTurn>=askScripts[askScenario].turns.length}
function askCard(title,desc,location,i,n,c){const place=askPlaces[title];return `<button type="button" class="ask-pick ${place?'has-photo':''}" data-action="ask-card" data-index="${n}" data-card="${c}" aria-label="More about ${escapeAsk(title)}">${place?`<img src="assets/ask-${place.image}.jpg" alt="${place.alt}">`:`<span class="ask-pick-icon">${icon(i)}</span>`}<span class="ask-pick-copy"><strong>${title}</strong><span>${desc}</span>${location?`<small>${icon('pin')}${location}</small>`:''}<span class="ask-card-link">${place?'Explore this place':'Find out more'} ${icon('arrow')}</span></span></button>`}
function askReply(r,n){return `<p>${r.text}</p>${r.image?`<img class="ask-branch-photo" src="assets/ask-${r.image}.jpg" alt="${r.alt}">`:''}${r.recommend?`<div class="ask-picks">${askCard(r.recommend,'Tap for more information.',r.location,'pin',n,-1)}</div>`:''}${r.cards?`<div class="ask-picks">${r.cards.map(([i,t,d,l],c)=>askCard(t,d,l,i,n,c)).join('')}</div>`:''}${r.location&&!r.recommend?`<div class="ask-location">${icon('pin')}<span>${r.location}</span></div>`:''}${r.phrase?`<blockquote class="ask-phrase" lang="en-AU">“${r.phrase}”</blockquote>`:''}${r.listen?btn(icon('speaker')+(r.listen.length>1?'Listen to phrases':'Listen'),'ask-listen','ask-reply-action',`data-index="${n}"`):''}${!r.mapVisible?askMapCard(r,n):''}${askTripButton(r,n)}`}
function openAskCard(n,c){if(askPending)return;const r=askMessages[n]?.reply;if(!r)return;const card=c===-1?['pin',r.recommend,'']:r.cards?.[c];if(!card)return;const [type,title,desc]=card,place=askPlaces[title];let reply;
if(place)reply={...place,map:'View on map',focus:title+' · '+place.location};
else if(type==='ask'&&title.startsWith('“'))reply={text:desc,phrase:title.replace(/[“”]/g,''),listen:[title.replace(/[“”]/g,'')]};
else if(title==='Toilets')reply={text:'Public toilets are available along <strong>Queen Street</strong> and at <strong>Queen’s Food Hall</strong>. Use the toilet symbols on the market map.',map:'View toilets on map',focus:'Public toilets · Queen Street & Queen’s Food Hall'};
else if(title==='Information Hub')reply={text:'Visit the <strong>Information Hub at F Shed Shop 1</strong>, on Queen Street. Staff can help with directions and market information.',map:'View location',focus:'Information Hub · F Shed Shop 1'};
else reply={text:'<strong>Saturday Market Hours</strong><br>6 AM–4 PM. Check the official visitor guide before visiting, as individual stalls and holiday hours can differ.',map:'View market map',focus:'Market overview'};
reply.mapVisible=askMapKeys(reply).length>0;askMessages.push({role:'user',text:'Tell me more about '+title.replace(/[“”]/g,'')+'.'},{role:'guide',reply});render(false);scrollAskReply()}

function resetAsk(){clearTimeout(askTimer);askGeneration++;askPending=false;askScenario=null;askTurn=0;askDraft='';askMessages=[];window.speechSynthesis?.cancel()}
function startAsk(id){if(askPending&&askScenario){askMessages.push({role:'guide',reply:askTripReply(askScripts[askScenario].turns[askTurn][1])})}clearTimeout(askTimer);askGeneration++;askPending=false;window.speechSynthesis?.cancel();askScenario=id;askTurn=0;const script=askScripts[id];if(script.intro)askMessages.push({role:'guide',reply:clone(script.intro)});askDraft=script.turns[0][0];render(false);if(script.intro)scrollAskReply()}
function scrollAskReply(){requestAnimationFrame(()=>{const el=$('.ask-conversation');el?.lastElementChild?.scrollIntoView({block:'nearest',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})})}
function sendAsk(){if(!askScenario||!askDraft||askPending||askDone())return;const pair=askScripts[askScenario].turns[askTurn],generation=askGeneration;askMessages.push({role:'user',text:pair[0]});askDraft='';askPending=true;render(false);scrollAskReply();askTimer=setTimeout(()=>{if(generation!==askGeneration)return;askMessages.push({role:'guide',reply:askTripReply(pair[1])});askTurn++;askPending=false;askDraft=askScripts[askScenario].turns[askTurn]?.[0]||'';if(state.screen==='askPlace'){render(false);scrollAskReply()}},650)}
function showAskMap(n){const r=askMessages[n]?.reply,keys=r&&askMapKeys(r);if(!keys?.length)return;const key=keys.includes(r.selectedMap)?r.selectedMap:keys[0],d=document.createElement('dialog');d.id='ask-map-dialog';d.setAttribute('aria-labelledby','ask-map-title');d.innerHTML=askLocalize(`<header><h2 id="ask-map-title">${askMapPlaces[key].name}</h2>${btn(icon('close'),'ask-map-close','iconbtn','aria-label="Close market map"')}</header><p>From: market entrance opposite Tram Stop 7</p>${askMapElement(key)}<p>Illustrative directions · Follow on-site signs</p>`);document.body.append(d);d.addEventListener('close',()=>{liveMaps=liveMaps.filter(m=>{if(d.contains(m.getContainer())){disposeMap(m);return false}return true});d.remove()});d.addEventListener('click',e=>{if(e.target===d){const b=d.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)d.close()}});d.showModal();initMaps()}

function listenAsk(n){const phrases=askMessages[n]?.reply?.listen;if(!phrases)return;if(!('speechSynthesis' in window)){toast('Audio is unavailable in this browser. Read the phrase above.');return}window.speechSynthesis.cancel();const speech=new SpeechSynthesisUtterance(phrases.join(' ... '));speech.lang='en-AU';speech.rate=.88;speech.onerror=()=>toast('Audio is unavailable. Read the phrase above.');window.speechSynthesis.speak(speech)}
